{
  "bioavailability_prediction": "high",
  "confidence": "low",
  "revision_action": "keep",
  "supportive_card_ids": ["C11", "C20", "C33", "C08", "C12", "C21", "C31", "C35", "C36", "C01", "C16"],
  "contradictory_card_ids": ["C25"],
  "prediction_basis_card_ids": ["C11", "C20", "C33", "C08", "C12", "C35", "C36", "C01", "C16"],
  "claims": [
    {
      "claim": "The closest lipophilic polyene context, zeaxanthin, is reported as highly bioavailable when ingested with fat and bioavailable from food matrices, supporting that highly lipophilic polyenes can achieve meaningful oral absorption.",
      "card_ids": ["C11", "C20", "C33"]
    },
    {
      "claim": "Leflunomide and teriflunomide, N-aryl amide drugs, show oral bioavailability of approximately 80-100% in humans, supporting that anilide-containing lipophilic drugs can exceed the 20% threshold.",
      "card_ids": ["C08", "C12", "C21", "C31", "C35", "C36"]
    },
    {
      "claim": "Desvenlafaxine, a phenol-containing drug, has absolute oral bioavailability of about 80%, showing that a phenolic group does not preclude F >= 20%.",
      "card_ids": ["C01", "C16"]
    },
    {
      "claim": "The apatinib L2 record of 10-20% bioavailability is structurally distant and low-transferability; it does not affirmatively establish F < 20% for the query.",
      "card_ids": ["C07", "C25"]
    },
    {
      "claim": "The new L3 estradiol oral exposure records provide Cmax and AUC values but no matched IV comparator or absolute bioavailability, and they concern a different steroid scaffold; they neither support nor refute F >= 20% for the query.",
      "card_ids": ["C37", "C38", "C39", "C40", "C41", "C42", "C43", "C44", "C45", "C46", "C47", "C48"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C37", "C38", "C39", "C40", "C41", "C42", "C43", "C44", "C45", "C46", "C47", "C48"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query retinoid amide is supplied.",
    "No matched oral-versus-IV exposure data or IV comparator for the query is available.",
    "Measured solubility, dissolution, and first-pass metabolism data for the query are absent; the high logP and unfavorable solubility prior are not endpoint proof.",
    "Formulation and fed/fasted conditions are unspecified; lipophilic retinoids often show food-dependent absorption.",
    "Structural transfer from zeaxanthin, anilide, and estradiol contexts is qualitative and limited."
  ],
  "decision_summary": "No affirmative threshold-relevant evidence supports F < 20% for the query; the closest lipophilic polyene and anilide contexts are directionally supportive of meaningful oral absorption, while the apatinib 10-20% record is low-transferability and the new L3 estradiol exposure records lack bioavailability endpoints and scaffold relevance. Therefore F >= 20% remains better supported, with low confidence."
}

